package cl.nexbyte.siger.institucional.notificaciones;
import java.nio.file.*;import java.nio.file.attribute.PosixFilePermissions;import java.time.*;import java.util.*;import java.io.*;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;import static org.junit.jupiter.api.Assertions.*;
class GraphMailServiceTest {
 @TempDir Path dir;Path secret;tools.jackson.databind.json.JsonMapper json=tools.jackson.databind.json.JsonMapper.builder().build();String synthetic=UUID.randomUUID()+"aZ";
 @BeforeEach void start()throws Exception{secret=dir.resolve("secreto-sintetico");Files.writeString(secret,synthetic);Files.setPosixFilePermissions(secret,PosixFilePermissions.fromString("rw-------"));}
 GraphMailService.Ajustes config(){return new GraphMailService.Ajustes("11111111-1111-1111-1111-111111111111","22222222-2222-2222-2222-222222222222","siger@example.invalid",secret);}
 TransporteCorreo.Mensaje message(){return new TransporteCorreo.Mensaje("qa@example.invalid","[SIGER LAB] TAREA_RECORDATORIO","Texto sintético sin relato",UUID.randomUUID().toString());}
 GraphMailService.Respuesta token(){return new GraphMailService.Respuesta(200,"{\"access_token\":\"TOKEN_SINTETICO_SIN_VALOR\",\"expires_in\":3600}".getBytes(),null,null);}
 @Test void protocoloReutilizadoSoloEnviaSecretoAOAuthYCacheaToken(){var calls=new ArrayList<String>();var client=new GraphMailService(config(),json,Clock.systemUTC(),(uri,headers,body)->{calls.add(uri.getHost());String data=new String(body,java.nio.charset.StandardCharsets.UTF_8);if(uri.getHost().equals("login.microsoftonline.com")){assertTrue(data.contains("client_credentials"));assertTrue(data.contains("client_secret="));assertFalse(headers.containsKey("Authorization"));return token();}assertEquals("graph.microsoft.com",uri.getHost());assertFalse(data.contains(synthetic));assertEquals("Bearer TOKEN_SINTETICO_SIN_VALOR",headers.get("Authorization"));return new GraphMailService.Respuesta(202,new byte[0],null,null);});assertEquals("ACCEPTED_BY_GRAPH",client.enviar(message()).estado());client.enviar(message());assertEquals(List.of("login.microsoftonline.com","graph.microsoft.com","graph.microsoft.com"),calls);}
 @Test void excepcionConCuerpoOSecretoNoSePropaga(){var client=new GraphMailService(config(),json,Clock.systemUTC(),(u,h,b)->{throw new IOException("RESERVADO "+synthetic);});var result=client.enviar(message());assertEquals("TOKEN",result.fase());assertEquals("REINTENTABLE",result.estado());assertFalse(result.toString().contains(synthetic));}
 @Test void timeoutEnSendEsAmbiguoYNoTieneCausaPrivada(){var client=new GraphMailService(config(),json,Clock.systemUTC(),(u,h,b)->{if(u.getHost().equals("login.microsoftonline.com"))return token();throw new java.net.http.HttpTimeoutException("Authorization RESERVADA");});var r=client.enviar(message());assertEquals("AMBIGUO",r.estado());assertNull(r.http());}
 @Test void permisosRechazadosY429NoSeConfundenConEntrega(){for(int code:List.of(400,401,403,429,500)){var client=new GraphMailService(config(),json,Clock.systemUTC(),(u,h,b)->u.getHost().equals("login.microsoftonline.com")?token():new GraphMailService.Respuesta(code,"CUERPO_REMOTO_NO_IMPRIMIR".getBytes(),"120","no-se-acepta-texto-libre"));var r=client.enviar(message());assertEquals(code==429?"REINTENTABLE":code>=500?"AMBIGUO":"RECHAZADO",r.estado());assertEquals(code,r.http());assertNull(r.requestId());assertEquals(120,r.reintentarEnSegundos());}}
 @Test void permisosDeArchivoNoSeOmitenYNuncaHayLlamada(){var calls=new int[1];assertDoesNotThrow(()->Files.setPosixFilePermissions(secret,PosixFilePermissions.fromString("rw-r--r--")));var client=new GraphMailService(config(),json,Clock.systemUTC(),(u,h,b)->{calls[0]++;return token();});assertEquals("REINTENTABLE",client.enviar(message()).estado());assertEquals(0,calls[0]);}
 @Test void respuestaDeTokenInvalidaORedireccionNoLlegaAGraph(){for(int status:List.of(200,302)){var calls=new int[1];var client=new GraphMailService(config(),json,Clock.systemUTC(),(u,h,b)->{calls[0]++;return new GraphMailService.Respuesta(status,"{\"error\":\"sintetico\"}".getBytes(),null,null);});assertNotEquals("ACCEPTED_BY_GRAPH",client.enviar(message()).estado());assertEquals(1,calls[0]);}}
}
